// The documentation site (site/) quotes numbers computed from the code: the RGAA routing,
// the per-source coverage, the W3C ACT score. They are GENERATED by `pnpm run build:site`
// (src/site-data.ts), never typed by hand — this test fails when the committed site drifts
// from a fresh generation, so a page can never advertise a coverage the engine no longer has.
//
// Regenerate with: pnpm run build:site
import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { buildSiteData, renderData, renderPage, SITE_PAGES } from "../src/site-data.js";

const root = new URL("..", import.meta.url).pathname;
const data = buildSiteData(root);
const site = (file: string): string => readFileSync(new URL(`../site/${file}`, import.meta.url), "utf8");

describe("site/ is generated from the code, never hand-edited", () => {
  it("site/data.json matches a fresh generation", () => {
    expect(site("data.json")).toBe(renderData(data));
  });

  for (const file of SITE_PAGES) {
    it(`site/${file} carries the current numbers`, () => {
      const html = site(file);
      expect(renderPage(html, file, data)).toBe(html);
    });
  }

  it("routes each criterion exactly like references/rgaa-automation.md", () => {
    const md = readFileSync(new URL("../skills/ultra11y/references/rgaa-automation.md", import.meta.url), "utf8");
    const routing: Record<string, string> = {
      deterministic: "det",
      "deterministic NC + AI residual": "nc",
      "AI + signals": "hint",
      AI: "llm",
    };
    const expected = Object.fromEntries([...md.matchAll(/^\| (\d+\.\d+) \|[^|]+\|[^|]+\|[^|]+\| ([^|]+?) \|$/gm)].map((m) => [m[1], routing[m[2] as string]]));
    expect(Object.keys(expected)).toHaveLength(data.rgaa.criteria);
    expect(Object.fromEntries(data.criteria.map((c) => [c.id, c.level]))).toEqual(expected);
  });

  it("never counts an advisory rule as evidence for a source", () => {
    for (const c of data.criteria) {
      if (c.decisive.length + c.signals.length === 0) expect(c.sources, c.id).toEqual([]);
    }
  });

  it("accounts for every failed ACT example", () => {
    const f = data.act.failed;
    expect(f.caught + f.missed + f.rendered + f.judgment + f.gap + f.deprecated + f.outside).toBe(f.total);
  });
});
